## 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

static int find(int x, int parent[]) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

static void unite(int a, int b, int parent[], int sz[]) {
    a = find(a, parent);
    b = find(b, parent);
    if (a == b) return;

    if (sz[a] < sz[b]) {
        int t = a;
        a = b;
        b = t;
    }

    parent[b] = a;
    sz[a] += sz[b];
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *parent = (int *)malloc((N + 1) * sizeof(int));
    int *dsu_sz = (int *)malloc((N + 1) * sizeof(int));
    int *deg = (int *)calloc(N + 1, sizeof(int));
    int *head = (int *)malloc((N + 1) * sizeof(int));

    for (int i = 1; i <= N; ++i) {
        parent[i] = i;
        dsu_sz[i] = 1;
        head[i] = -1;
    }

    int maxEdges = 2 * M + 5;
    int *to = (int *)malloc(maxEdges * sizeof(int));
    int *nxt = (int *)malloc(maxEdges * sizeof(int));
    int edgeIdx = 0;

    for (int i = 0; i < M; ++i) {
        int u, v;
        scanf("%d %d", &u, &v);

        deg[u]++;
        deg[v]++;

        to[edgeIdx] = v;
        nxt[edgeIdx] = head[u];
        head[u] = edgeIdx++;

        to[edgeIdx] = u;
        nxt[edgeIdx] = head[v];
        head[v] = edgeIdx++;

        unite(u, v, parent, dsu_sz);
    }

    int *root = (int *)malloc((N + 1) * sizeof(int));
    int *comp_size = (int *)calloc(N + 1, sizeof(int));
    long long *edge_count = (long long *)calloc(N + 1, sizeof(long long));

    for (int v = 1; v <= N; ++v) {
        root[v] = find(v, parent);
        comp_size[root[v]]++;
        edge_count[root[v]] += deg[v];
    }

    for (int v = 1; v <= N; ++v) {
        if (comp_size[v] > 0) {
            edge_count[v] /= 2;
        }
    }

    int chosen = -1;

    for (int v = 1; v <= N; ++v) {
        if (comp_size[v] >= 2) {
            long long maxEdgesComp =
                (long long)comp_size[v] * (comp_size[v] - 1) / 2;

            if (edge_count[v] < maxEdgesComp) {
                chosen = v;
                break;
            }
        }
    }

    if (chosen == -1) {
        printf("-1\n");
        return 0;
    }

    int s = comp_size[chosen];
    int u = -1;

    for (int v = 1; v <= N; ++v) {
        if (root[v] == chosen && deg[v] < s - 1) {
            u = v;
            break;
        }
    }

    int *mark = (int *)calloc(N + 1, sizeof(int));

    for (int e = head[u]; e != -1; e = nxt[e]) {
        mark[to[e]] = 1;
    }

    int w = -1;

    for (int v = 1; v <= N; ++v) {
        if (v != u && root[v] == chosen && !mark[v]) {
            w = v;
            break;
        }
    }

    printf("%d %d\n", u, w);

    return 0;
}
```

